files.backend/build.gradle:
plugins {
    id 'java'
}

group = 'com.vireocode'
version = '0.0.1-SNAPSHOT'
description = 'VireoCode Web App Starter backend'

dependencies {
    implementation 'org.example:preserved-dependency:1.2.3'
}

files.backend/scripts/start-local.mjs:
// The fallback belongs to the consumer; the credential guard stays intact.
export function configuredEnvironment(values) {
  const env = {};
  env.COMPOSE_PROJECT_NAME =
    values.COMPOSE_PROJECT_NAME || "vireocode-web-app-starter-local";
  if (!values.POSTGRES_PASSWORD) throw new Error("Existing credentials must be preserved");
  return env;
}

files..vscode/launch.json:
{
  "version": "0.2.0",
  "configurations": [
    {
      "name": "Frontend: local dev",
      "type": "node-terminal",
      "request": "launch",
      "command": "npm run dev",
      "cwd": "${workspaceFolder}/frontend"
    },
    {
      "name": "Backend: local dev",
      "type": "java",
      "request": "launch",
      "mainClass": "com.vireocode.backend.BackendApplication",
      "envFile": "${workspaceFolder}/backend/.env",
      "args": "--spring.profiles.active=local",
      "preLaunchTask": "Backend: start local PostgreSQL"
    }
  ]
}

